import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.AddBehaviourTree{BehaviourTree: "{\"behaviors\":[\"minecraft:behavior.float\"]}"}
GOLDEN = bytes.fromhex("2a7b226265686176696f7273223a5b226d696e6563726166743a6265686176696f722e666c6f6174225d7d")

# generated by gophertunnel b8bd735:
# packet.AddBehaviourTree{BehaviourTree: ""}
EMPTY = bytes.fromhex("00")

# generated by gophertunnel b8bd735:
# packet.AddBehaviourTree{BehaviourTree: strings.Repeat("a", 200)}
LONG = bytes.fromhex(
    ""
)

GOLDENS = [
    pytest.param(
        v2225.AddBehaviorTreePacket(json_input='{"behaviors":["minecraft:behavior.float"]}'),
        GOLDEN,
        id="behaviors",
    ),
    pytest.param(v2225.AddBehaviorTreePacket(), EMPTY, id="empty-is-a-lone-length-prefix"),
    pytest.param(v2225.AddBehaviorTreePacket(json_input="a" * 200), LONG, id="length-prefix-is-a-varint"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_add_behavior_tree_is_packet_89(version):
    assert version.PACKETS[89] is version.AddBehaviorTreePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_add_behavior_tree_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_add_behavior_tree_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
